#define MAXDIM 1024
#define MAXTRANS 1024

int xtrans[MAXTRANS][2]; // sign, offset
int ytrans[MAXTRANS][2];
int nx, ny;

int holes[MAXDIM][MAXDIM];

int main() {
    int W, H;
    scanf("%d %d", &W, &H);

    nx = 1; ny = 1;
    xtrans[0][0] = 1; xtrans[0][1] = 0;
    ytrans[0][0] = 1; ytrans[0][1] = 0;

    int N;
    scanf("%d", &N);

    for (int i = 0; i < N; i++) {
        char op[10];
        scanf("%s", op);
        if (strcmp(op, "fold") == 0) {
            char axis[3];
            int val;
            scanf("%s %d", axis, &val);
            if (axis[0] == 'x') {
                // fold at x=val
                for (int j = 0; j < nx; j++) {
                    xtrans[nx+j][0] = -xtrans[j][0];
                    xtrans[nx+j][1] = 2*val*xtrans[j][0] + xtrans[j][1];
                }
                nx *= 2;
            } else {
                for (int j = 0; j < ny; j++) {
                    ytrans[ny+j][0] = -ytrans[j][0];
                    ytrans[ny+j][1] = 2*val*ytrans[j][0] + ytrans[j][1];
                }
                ny *= 2;
            }
        } else { // punch
            int px, py;
            scanf("%d %d", &px, &py);
            for (int xi = 0; xi < nx; xi++) {
                int ox = xtrans[xi][0]*px + xtrans[xi][1];
                if (ox < 0 || ox >= W) continue;
                for (int yi = 0; yi < ny; yi++) {
                    int oy = ytrans[yi][0]*py + ytrans[yi][1];
                    if (oy < 0 || oy >= H) continue;
                    holes[ox][oy] = 1;
                }
            }
        }
    }

    int count = 0;
    for (int x = 0; x < W; x++)
        for (int y = 0; y < H; y++)
            count += holes[x][y];

    printf("%d\n", count);
    return 0;
}

