                    Rect right = {k, r.y1, r.x2, r.y2};
                    Rect tright = {2 * k - right.x2, right.y1, 2 * k - right.x1, right.y2};
                    next[m++] = left;
                    next[m++] = tright;
                }
            } else if (dir[0] == 'B') {
                if (r.y2 <= k) {
                    Rect t = {r.x1, 2 * k - r.y2, r.x2, 2 * k - r.y1};
                    next[m++] = t;
                } else if (r.y1 >= k) {
                    next[m++] = r;
