                    Rect bot = {r.x1, r.y1, r.x2, k};
                    Rect top = {r.x1, k, r.x2, r.y2};
                    Rect tbot = {bot.x1, 2 * k - bot.y2, bot.x2, 2 * k - bot.y1};
