                    next[m++] = top;
                }
            } else { /* Top */
                if (r.y1 >= k) {
                    Rect t = {r.x1, 2 * k - r.y2, r.x2, 2 * k - r.y1};
                    next[m++] = t;
                } else if (r.y2 <= k) {
                    next[m++] = r;
                } else {
                    Rect bot = {r.x1, r.y1, r.x2, k};
                    Rect top = {r.x1, k, r.x2, r.y2};
                    Rect ttop = {top.x1, 2 * k - top.y2, top.x2, 2 * k - top.y1};
                    next[m++] = bot;
                    next[m++] = ttop;
                }
            }
        }

        free(rects);
        rects = next;
        n = m;
        cap = nextCap;
    }

    int P;
    scanf("%d", &P);

    while (P--) {
        ll x, y;
