// folds: (axis, position) axis=0 means fold along x=pos (vertical fold), axis=1 means fold along y=pos
vector<pair<int,int>> folds;

set<pair<int,int>> unfold(int x, int y, int foldIdx) {
    if (foldIdx < 0) {
        if (x >= 0 && x < W && y >= 0 && y < H)
            return {{x, y}};
        return {};
    }
    auto [axis, pos] = folds[foldIdx];
    set<pair<int,int>> result;
    // This point came from two possible original points before this fold
    // axis=0: fold along x=pos
    if (axis == 0) {
        auto s1 = unfold(x, y, foldIdx-1);
        auto s2 = unfold(2*pos - x, y, foldIdx-1);
        result.insert(s1.begin(), s1.end());
        result.insert(s2.begin(), s2.end());
    } else {
        auto s1 = unfold(x, y, foldIdx-1);
        auto s2 = unfold(x, 2*pos - y, foldIdx-1);
        result.insert(s1.begin(), s1.end());
        result.insert(s2.begin(), s2.end());
    }
    return result;
}

