/*
We model the paper as a set of axis-aligned unit squares.
Initially: rectangle [0..W-1] x [0..H-1].

A fold along x = c:
- keep the side containing the line's "base side":
  * L : fold right part onto left  => resulting x in [0, c-1]
  * R : fold left part onto right => resulting x in [c, W-1]
For every existing layer cell, it maps to its reflected position if it is on the folded side.
Counts add up.

Similarly for horizontal folds:
  * T : fold bottom onto top? We use coordinates y increasing downward? To avoid ambiguity,
    we only need consistency with reflection formulas.
We use y increasing upward from 0..H-1 and:
  * B : fold upper part downward onto lower, keep [0, c-1]
  * T : fold lower part upward onto upper, keep [c, H-1]

After all folds, punches are given in the final folded state; each punch through one visible cell
creates as many holes as there are layers at that cell.

Input format assumed (classic "holes in folded paper"):
W H
F
<dir> <coord>   repeated F times
P
x y             repeated P times

Output total number of holes.

This implementation supports that format.
*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int W, H;
    if (!(cin >> W >> H)) return 0;

    int F;
    cin >> F;

    map<pair<int,int>, long long> layers;
    for (int x = 0; x < W; ++x)
        for (int y = 0; y < H; ++y)
            layers[{x,y}] = 1;

    int curW = W, curH = H;
    int x0 = 0, y0 = 0; // current coordinate ranges are [x0, x0+curW-1], [y0, y0+curH-1]

    for (int i = 0; i < F; ++i) {
        char d;
        int c;
        cin >> d >> c;

        map<pair<int,int>, long long> nxt;

        if (d == 'L') {
            // fold right side onto left, keep x in [x0, c-1]
            for (auto &it : layers) {
                int x = it.first.first, y = it.first.second;
                long long v = it.second;
                int nx = x;
                if (x >= c) nx = 2 * c - 1 - x;
                nxt[{nx, y}] += v;
            }
            curW = c - x0;
        } else if (d == 'R') {
            // fold left side onto right, keep x in [c, x0+curW-1]
            for (auto &it : layers) {
                int x = it.first.first, y = it.first.second;
                long long v = it.second;
                int nx = x;
                if (x < c) nx = 2 * c - 1 - x;
                nxt[{nx, y}] += v;
            }
            x0 = c;
            curW = x0 + curW - c;
        } else if (d == 'B') {
            // fold upper side downward onto lower, keep y in [y0, c-1]
            for (auto &it : layers) {
                int x = it.first.first, y = it.first.second;
                long long v = it.second;
                int ny = y;
                if (y >= c) ny = 2 * c - 1 - y;
                nxt[{x, ny}] += v;
            }
            curH = c - y0;
        } else if (d == 'T') {
            // fold lower side upward onto upper, keep y in [c, y0+curH-1]
            for (auto &it : layers) {
                int x = it.first.first, y = it.first.second;
                long long v = it.second;
                int ny = y;
                if (y < c) ny = 2 * c - 1 - y;
                nxt[{x, ny}] += v;
            }
            y0 = c;
            curH = y0 + curH - c;
        }

        layers.swap(nxt);
    }

    int P;
    cin >> P;
    long long ans = 0;
    for (int i = 0; i < P; ++i) {
        int x, y;
        cin >> x >> y;
        auto it = layers.find({x, y});
        if (it != layers.end()) ans += it->second;
    }

    cout << ans << '\n';
    return 0;
}

