 *
 * Each point punched on the folded stack corresponds, after unfolding, to one point
 * in every mirrored copy created by each fold. We can process folds in reverse:
 * starting from a punched point on the final folded rectangle, undo each fold and
 * duplicate/mirror all current points accordingly.
 *
 * Input format assumed:
 *   W H
 *   F
 *   <F fold instructions>
 *   P
 *   <P punch points>
 *
 * Fold instruction:
 *   L x   fold left part right along vertical line x
 *   R x   fold right part left along vertical line x
 *   B y   fold bottom part up along horizontal line y
 *   T y   fold top part down along horizontal line y
 *
 * Punch points are given on the final folded paper as:
 *   x y
 *
 * Output:
 *   First the total number of holes after unfolding,
 *   then all distinct hole coordinates in increasing x, then y order, one per line.
 *
 * This is the standard interpretation of the classic paper-folding punch problem.
 */
public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static class Fold {
        char dir;
        int v;
        Fold(char dir, int v) {
            this.dir = dir;
            this.v = v;
        }
    }

    static class Point {
        int x, y;
        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    static long encode(int x, int y) {
        return (((long) x) << 32) ^ (y & 0xffffffffL);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        String first = fs.next();
        if (first == null) return;

        int W = Integer.parseInt(first);
        int H = fs.nextInt();

        int F = fs.nextInt();
        Fold[] folds = new Fold[F];
        for (int i = 0; i < F; i++) {
            char d = fs.next().charAt(0);
            int v = fs.nextInt();
            folds[i] = new Fold(d, v);
        }

        int P = fs.nextInt();

        HashSet<Long> current = new HashSet<>();
        for (int i = 0; i < P; i++) {
            int x = fs.nextInt();
            int y = fs.nextInt();
            current.add(encode(x, y));
        }

        // Undo folds in reverse order.
        for (int i = F - 1; i >= 0; i--) {
            Fold f = folds[i];
            HashSet<Long> next = new HashSet<>(current.size() * 2 + 1);

            if (f.dir == 'L') {
                // Original left part folded right across x=v.
                // Reverse: each point on folded result gives:
                //   (x, y) on right side and mirrored (2v - x, y) on left side.
                for (long code : current) {
                    int x = (int) (code >> 32);
                    int y = (int) code;
                    next.add(encode(x, y));
                    next.add(encode(2 * f.v - x, y));
                }
            } else if (f.dir == 'R') {
                // Original right part folded left across x=v.
                for (long code : current) {
                    int x = (int) (code >> 32);
                    int y = (int) code;
                    next.add(encode(x, y));
                    next.add(encode(2 * f.v - x, y));
                }
            } else if (f.dir == 'B') {
                // Original bottom part folded up across y=v.
                for (long code : current) {
                    int x = (int) (code >> 32);
                    int y = (int) code;
                    next.add(encode(x, y));
                    next.add(encode(x, 2 * f.v - y));
                }
            } else if (f.dir == 'T') {
                // Original top part folded down across y=v.
                for (long code : current) {
                    int x = (int) (code >> 32);
                    int y = (int) code;
                    next.add(encode(x, y));
                    next.add(encode(x, 2 * f.v - y));
                }
            }

            current = next;
        }

        ArrayList<Point> ans = new ArrayList<>(current.size());
        for (long code : current) {
            ans.add(new Point((int) (code >> 32), (int) code));
        }

        ans.sort((a, b) -> {
            if (a.x != b.x) return Integer.compare(a.x, b.x);
            return Integer.compare(a.y, b.y);
        });

        StringBuilder out = new StringBuilder();
        out.append(ans.size()).append('\n');
        for (Point p : ans) {
            out.append(p.x).append(' ').append(p.y).append('\n');
        }
        System.out.print(out.toString());
    }
}
